import React from 'react';
import BookCard from './BookCard';

const books = [
    {
      id: 1,
      title: "7 чоловіків Евілін Г'юго",
      imgSrc: "/7-mans-evelin-gugo.jpg",
      description: "Уже літня та замкнута в собі голлівудська ікона кіно Евелін Хьюго нарешті готова розповісти правду про своє гламурне та скандальне життя..."
    },
    {
      id: 2,
      title: "9 листопада",
      imgSrc: "/9-november.png",
      description: "Як знати, що кохання справжнє? А який він — любовний поцілунок як у книжках?..."
    },
    {
      id: 3,
      title: "Так тобі й треба",
      imgSrc: "/tak-tobi-i-treba.webp",
      description: "«Не хочу рівно, хочу, як у кіно». Від першої закоханості й метеликів у животі до конфліктів та важких рішень..."
    }
];

function CatalogPage() {
  return (
    <div>
      <h1>Каталог</h1>
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
        gap: '20px',
        padding: '20px'
      }}>
        {books.map(book => (
          <BookCard 
            key={book.id}
            title={book.title}
            imgSrc={book.imgSrc}
            description={book.description}
          />
        ))}
      </div>
    </div>
  );
}

export default CatalogPage;
